import{c as e,Q as t,j as r,m as l}from"./chunks/framework.BPKcPtvA.js";const m=JSON.parse('{"title":"RO3 首支完整实机预告片公开 致敬所有真正的 RO 玩家","description":"Gravity 发布 RO3 首支完整实机宣传片，展示职业、副本、GVG 等核心玩法","frontmatter":{"title":"RO3 首支完整实机预告片公开 致敬所有真正的 RO 玩家","description":"Gravity 发布 RO3 首支完整实机宣传片，展示职业、副本、GVG 等核心玩法"},"headers":[],"relativePath":"news/gameplay-trailer-202507.md","filePath":"news/gameplay-trailer-202507.md","lastUpdated":1779114430000}'),o={name:"news/gameplay-trailer-202507.md"};function i(s,a,n,p,d,c){return t(),r("div",null,[...a[0]||(a[0]=[l('<h1 id="首支完整实机预告片公开" tabindex="-1">首支完整实机预告片公开 <a class="header-anchor" href="#首支完整实机预告片公开" aria-label="Permalink to &quot;首支完整实机预告片公开&quot;">​</a></h1><p>日期：2025-07-31</p><p>Gravity 与 JoyMaker 正式发布 RO3 首支完整实机宣传片，片长 3 分钟，展示从初心者到进阶职业的成长历程，以及多种核心玩法画面。</p><h2 id="预告片看点" tabindex="-1">预告片看点 <a class="header-anchor" href="#预告片看点" aria-label="Permalink to &quot;预告片看点&quot;">​</a></h2><ul><li><strong>经典职业回归</strong> — 骑士、猎人、十字军等经典职业实机战斗展示</li><li><strong>十人副本</strong> — 强调互动机制的副本玩法首次亮相</li><li><strong>GVG 公会联赛</strong> — 大规模公会战画面</li><li><strong>普隆德拉、梦罗克</strong>等经典场景以全新 3D 美术重制</li><li><strong>多元宇宙</strong>设定片段</li></ul><p>官方在预告片描述中写道：</p><blockquote><p>你是否还记得踏进米德加尔特的第一步？是否还记得普隆德拉南门外的聚散离合？今天，我们的故事翻开新篇章。</p></blockquote><h2 id="先锋测试同步招募" tabindex="-1">先锋测试同步招募 <a class="header-anchor" href="#先锋测试同步招募" aria-label="Permalink to &quot;先锋测试同步招募&quot;">​</a></h2><p>伴随预告片发布，官方同步开启「先锋测试」招募，面向台港澳、韩国、泰国、印尼、新加坡、马来西亚、菲律宾等地区的玩家开放限量测试资格申请。</p><p><small>来源：官方 YouTube 频道</small></p>',10)])])}const h=e(o,[["render",i]]);export{m as __pageData,h as default};
